INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT138-S2-Q19$batch10$, 138, 2, 19, $batch10$Main Conclusion$batch10$, $batch10$Research into artificial intelligence will fail to produce truly intelligent machines unless the focus of the discipline is radically changed. Progress has been made in creating devices of tremendous computational sophistication, but the present focus on computational ability to the exclusion of other abilities will produce devices only as capable of displaying true intelligence as a human being would be who was completely devoid of emotional and other noncognitive responses.$batch10$, $batch10$Which one of the following most accurately expresses the main conclusion argued for above?$batch10$, $batch10$B$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=138 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT138-S2-Q19$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$The current focus of research into artificial intelligence will produce devices no more capable of displaying true intelligence than a person would be who lacked emotions and other noncognitive responses.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT138-S2-Q19$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$If the current focus of research into artificial intelligence is not radically changed, this research will not be able to produce machines capable of true intelligence.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT138-S2-Q19$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$Despite progress in creating machines of great computational sophistication, current research into artificial intelligence has failed to fulfill its objectives.$batch10$, $batch10$Not Stated$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT138-S2-Q19$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$The capacity to express noncognitive responses such as emotion is at least as important for true intelligence as is computational sophistication.$batch10$, $batch10$Too Strong$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT138-S2-Q19$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$If a machine is not capable of producing humanlike noncognitive responses, then it cannot be regarded as truly intelligent.$batch10$, $batch10$Assumption, Not Conclusion$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT138-S2-Q19$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT138-S2-Q19$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$Unless the field's focus changes radically, AI research won't produce truly intelligent machines.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The current focus is on computational ability to the exclusion of everything else. That will produce devices no more truly intelligent than a person with no emotional or other noncognitive responses.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The first sentence states the claim, and the second explains why. "Unless X, not Y" is the same as "If not X, then not Y."$batch10$), (3, $batch10$Goal$batch10$, $batch10$If AI research's focus is not radically changed, it won't produce truly intelligent machines.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT138-S2-Q19$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is the second sentence, the reason the focus must change.$batch10$), ($batch10$B$batch10$, $batch10$"Unless the focus is radically changed, research will fail" translates to "If the focus is not radically changed, research won't produce true intelligence." That's the first sentence.$batch10$), ($batch10$C$batch10$, $batch10$The author says the research will fail, not that it already has.$batch10$), ($batch10$D$batch10$, $batch10$The argument implies noncognitive responses matter for true intelligence. It never says they matter at least as much as computation.$batch10$), ($batch10$E$batch10$, $batch10$This is closer to something the argument relies on. The conclusion is about what AI research will achieve.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT138-S2-Q19$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
